INSERT INTO trips
SELECT toUInt32(trip_id), toDate(pickup_date),
       toDateTime(pickup_datetime, 'UTC'), toDateTime(dropoff_datetime, 'UTC'),
       toDecimal64(tip_amount, 2), toDecimal64(total_amount, 2), pickup_ntaname
FROM file('trips_{1..2}.gz', 'TabSeparatedWithNames', '`trip_id` String, `vendor_id` String, `pickup_date` String, `pickup_datetime` String, `dropoff_date` String, `dropoff_datetime` String, `store_and_fwd_flag` String, `rate_code_id` String, `pickup_longitude` String, `pickup_latitude` String, `dropoff_longitude` String, `dropoff_latitude` String, `passenger_count` String, `trip_distance` String, `fare_amount` String, `extra` String, `mta_tax` String, `tip_amount` String, `tolls_amount` String, `ehail_fee` String, `improvement_surcharge` String, `total_amount` String, `payment_type` String, `trip_type` String, `pickup` String, `dropoff` String, `cab_type` String, `pickup_nyct2010_gid` String, `pickup_ctlabel` String, `pickup_borocode` String, `pickup_ct2010` String, `pickup_boroct2010` String, `pickup_cdeligibil` String, `pickup_ntacode` String, `pickup_ntaname` String, `pickup_puma` String, `dropoff_nyct2010_gid` String, `dropoff_ctlabel` String, `dropoff_borocode` String, `dropoff_ct2010` String, `dropoff_boroct2010` String, `dropoff_cdeligibil` String, `dropoff_ntacode` String, `dropoff_ntaname` String, `dropoff_puma` String');
